<script setup lang="ts">
import { computed, nextTick, onMounted, ref, watch } from "vue";
import { useRoute } from "vue-router";
import { useWorkspaceStore } from "../stores/workspace";
import WorkspaceFilters from "../components/WorkspaceFilters.vue";
import LocalAsset from "../components/LocalAsset.vue";
import { downloadLocalBlob } from "../lib/exportBundle";
import type { MediaAsset, ReviewStatus } from "../types/dataset";
import { useModalFocus } from "../composables/useModalFocus";

const workspace = useWorkspaceStore();
const route = useRoute();
const visibleLimit = ref(24);
const selected = ref(new Set<string>());
const focused = ref<MediaAsset | null>(null);
const preview = ref<{ ids: string[]; status: ReviewStatus; revision: string; description: string } | null>(null);
const saveMessage = ref("");
const restoreInput = ref<HTMLInputElement | null>(null);
const currentRevision = computed(() => JSON.stringify({ dataset: workspace.dataset?.fingerprint, datasetRevision: workspace.dataset?.revision, query: workspace.query, decisions: workspace.decisions }));
const visible = computed(() => workspace.filteredAssets.slice(0, visibleLimit.value));
const contextEvents = computed(() => focused.value ? workspace.selectedEvents.filter((event) => event.assetIds.includes(focused.value!.id)) : []);
const associatedLinks = computed(() => focused.value ? (workspace.dataset?.links ?? []).filter((link) => link.assetId === focused.value!.id && workspace.selectedEvents.some((event) => event.id === link.eventId)) : []);
const decisionsCount = computed(() => Object.keys(workspace.decisions).length);
const reviewLaterCount = computed(() => Object.values(workspace.decisions).filter((decision) => decision.status === "later").length);
const sourceLabel = (asset: MediaAsset) => asset.source.path.startsWith("memories/") || asset.source.path.includes("memories_history") ? "Memories" : asset.source.path.startsWith("chat_media/") || asset.conversationIds.length ? "Conversation media" : "Unlinked archive media";
function formatDate(timestamp: string | null) { return timestamp ? new Intl.DateTimeFormat("en", { dateStyle: "medium", timeZone: workspace.dataset?.timezone ?? "UTC" }).format(new Date(timestamp)) : "Date not recorded"; }
function title(asset: MediaAsset) { return asset.kind === "video" ? "A moment in motion" : asset.kind === "image" ? "A little time capsule" : `Recorded ${asset.kind}`; }
function status(id: string): ReviewStatus | "unreviewed" { return workspace.decisions[id]?.status ?? "unreviewed"; }
function toggle(id: string) { const changed = new Set(selected.value); changed.has(id) ? changed.delete(id) : changed.add(id); selected.value = changed; }
function previewBatch(reviewStatus: ReviewStatus) { if (selected.value.size) preview.value = { ids: [...selected.value], status: reviewStatus, revision: currentRevision.value, description: `${selected.value.size} explicitly selected media records` }; }
function previewPersonExclusion() {
	const dataset = workspace.dataset;
	if (!dataset || !workspace.query.participantId) return;
	const participant = dataset.participants.find((person) => person.id === workspace.query.participantId);
	const conversations = new Set(dataset.conversations.filter((conversation) => conversation.participantIds.includes(workspace.query.participantId!)).map((conversation) => conversation.id));
	const events = dataset.events.filter((event) => conversations.has(event.conversationId) || event.participantId === workspace.query.participantId);
	const eventIds = new Set(events.map((event) => event.id));
	const assetIds = new Set([...events.flatMap((event) => event.assetIds), ...dataset.assets.filter((asset) => asset.conversationIds.some((id) => conversations.has(id))).map((asset) => asset.id)]);
	preview.value = { ids: [...eventIds, ...assetIds], status: "exclude", revision: currentRevision.value, description: `${participant?.displayName ?? "This person"}'s recorded context: ${events.length} events in ${conversations.size} conversations and ${assetIds.size} media records. This includes your words in shared conversations and shared media in other rooms. Unrecorded or uncertain membership cannot be detected.` };
}
function applyPreview() { const proposal = preview.value; if (!proposal || proposal.revision !== currentRevision.value) return; workspace.batchDecide(proposal.ids, proposal.status); preview.value = null; selected.value = new Set(); }
function closeViewer() { const id = focused.value?.id; focused.value = null; if (id) nextTick(() => document.querySelector<HTMLElement>(`[data-asset-id="${CSS.escape(id)}"] .open-asset`)?.focus()); }
const viewerDialog = useModalFocus(() => Boolean(focused.value), closeViewer);
const previewDialog = useModalFocus(() => Boolean(preview.value), () => { preview.value = null; });
function saveReviewState() {
	if (!workspace.dataset) return;
	downloadLocalBlob(new Blob([workspace.exportReviewState()], { type: "application/json" }), "goodbye-chat-review-state.json");
	saveMessage.value = "Review state saved locally. Keep it private. Open the same ZIPs, then use Restore review state to apply this file.";
}
async function restoreReviewState(event: Event) {
	const input = event.target as HTMLInputElement;
	const file = input.files?.[0];
	if (!file) return;
	try {
		if (file.size > 10 * 1024 * 1024) throw new Error("This review-state file exceeds the supported 10 MiB size.");
		workspace.restoreReviewState(await file.text());
		saveMessage.value = "Your matching review state was restored locally. Original archive files remain unchanged.";
	} catch (failure) { saveMessage.value = failure instanceof Error ? failure.message : "These decisions could not be restored."; }
	finally { input.value = ""; }
}
watch(() => [workspace.query, workspace.dataset?.fingerprint], () => { visibleLimit.value = 24; selected.value = new Set(); focused.value = null; }, { deep: true });
watch(() => [route.query.asset, workspace.dataset], () => { if (typeof route.query.asset === "string") focused.value = workspace.filteredAssets.find((asset) => asset.id === route.query.asset) ?? null; }, { immediate: true });
watch(() => workspace.decisions, () => { if (focused.value && !workspace.filteredAssets.some((asset) => asset.id === focused.value?.id)) focused.value = null; }, { deep: true });
onMounted(() => { if (!workspace.dataset) workspace.loadFromArchive(); });
</script>

<template>
	<div class="page library-page"><div class="container">
		<header class="library-heading"><div><span class="eyebrow">The memory library</span><h1>Some things<br>are worth keeping.</h1></div><div class="collection-note"><span>{{ workspace.selectedAssets.length }}</span><p>media records in your collection</p><router-link to="/export">Take them with you <span aria-hidden="true">↗</span></router-link></div></header>
		<WorkspaceFilters />
		<div class="review-toolbar"><p>{{ workspace.filteredAssets.length }} matching media records<span v-if="reviewLaterCount"> · {{ reviewLaterCount }} decisions for later</span></p><div><button :disabled="!workspace.canUndo" @click="workspace.undo()">Undo</button><button :disabled="!workspace.canRedo" @click="workspace.redo()">Redo</button><button :disabled="!decisionsCount" @click="saveReviewState">Save review state</button><button @click="restoreInput?.click()">Restore review state</button><input ref="restoreInput" type="file" accept="application/json,.json" hidden @change="restoreReviewState"><button v-if="workspace.query.participantId" @click="previewPersonExclusion">Exclude this person's context</button></div></div>
		<p v-if="saveMessage" class="save-message" role="status">{{ saveMessage }}</p>
		<div v-if="selected.size" class="batch-bar"><span>{{ selected.size }} media records selected</span><div><button @click="previewBatch('keep')">Keep selected</button><button @click="previewBatch('exclude')">Exclude selected</button><button @click="previewBatch('later')">Review later</button><button @click="selected = new Set()">Clear selection</button></div></div>
		<div v-if="workspace.loading" class="empty-library" role="status">Opening your local memory library...</div>
		<div v-else-if="workspace.error" class="empty-library" role="alert">{{ workspace.error }}<button class="btn btn-secondary" @click="workspace.loadFromArchive()">Try again</button></div>
		<div v-else-if="!visible.length" class="empty-library"><h2>Nothing here, yet.</h2><p>No media records match this selection. Your original files remain unchanged.</p><button class="btn btn-secondary" @click="workspace.resetQuery()">Clear filters</button></div>
		<div v-else class="library-grid"><article v-for="(asset, index) in visible" :key="asset.id" class="memory-card" :class="{ kept: status(asset.id) === 'keep', excluded: status(asset.id) === 'exclude', selected: selected.has(asset.id) }" :data-asset-id="asset.id"><div class="memory-top"><label class="selection-check"><input type="checkbox" :checked="selected.has(asset.id)" :aria-label="`Select ${asset.kind} ${formatDate(asset.timestamp)}`" @change="toggle(asset.id)"><span>{{ String(index + 1).padStart(2,'0') }}</span></label><span class="source-tag">{{ sourceLabel(asset) }}</span><span v-if="status(asset.id) !== 'unreviewed'" class="status-tag">{{ status(asset.id) }}</span></div><button class="open-asset" :aria-label="`Open ${asset.kind} ${formatDate(asset.timestamp)}`" @click="focused = asset"><LocalAsset :asset-id="asset.id" :path="asset.path" :overlay-path="asset.overlayPath" :kind="asset.kind" :label="`Recorded ${asset.kind} from ${formatDate(asset.timestamp)}`" /></button><div class="memory-caption"><h2>{{ title(asset) }}</h2><p>{{ formatDate(asset.timestamp) }} <span>{{ asset.kind }}</span></p></div><div class="memory-actions"><button :class="{ active: status(asset.id) === 'keep' }" @click="workspace.decide(asset.id, 'keep')">Keep</button><button :class="{ active: status(asset.id) === 'later' }" @click="workspace.decide(asset.id, 'later')">Later</button><button :class="{ active: status(asset.id) === 'exclude' }" @click="workspace.decide(asset.id, 'exclude')">Exclude</button></div></article></div>
		<button v-if="visibleLimit < workspace.filteredAssets.length" class="btn btn-secondary load-more" @click="visibleLimit += 24">Open more memories · {{ workspace.filteredAssets.length - visibleLimit }} remaining</button>
		<p class="library-footnote">Keep, exclude, and later are reversible decisions. Your original archive stays intact. Missing files and uncertain context are part of the record.</p>
	</div>
	<div v-if="focused" :ref="viewerDialog" tabindex="-1" class="viewer-overlay" role="dialog" aria-modal="true" aria-label="Memory and its context" @click.self="closeViewer" @keydown.esc="closeViewer"><section class="memory-viewer"><button class="close-viewer" @click="closeViewer" autofocus>Close</button><div class="viewer-layout"><LocalAsset :asset-id="focused.id" :path="focused.path" :overlay-path="focused.overlayPath" :kind="focused.kind" focused /><aside><span class="eyebrow">A memory in context</span><h2>{{ formatDate(focused.timestamp) }}</h2><p>{{ sourceLabel(focused) }} · {{ focused.kind }} · {{ status(focused.id) }}</p><p v-if="focused.overlayPath">Its separate overlay is shown over the available original.</p><h3>Recorded conversation context</h3><router-link v-for="event in contextEvents" :key="event.id" class="context-link" :to="{ path: '/conversations', query: { conversation: event.conversationId, event: event.id } }">{{ workspace.dataset?.conversations.find(conversation => conversation.id === event.conversationId)?.title ?? 'Recorded exchange' }}<small>{{ event.text || `Recorded ${event.kind} event` }}</small><span>Open this moment ↗</span></router-link><p v-if="!contextEvents.length" class="context-gap">No confirmed conversation is available in this collection. A timestamp alone cannot establish who received this media.</p><details v-for="link in associatedLinks" :key="link.id" class="association-evidence"><summary>{{ link.status }} association evidence</summary><p>{{ link.basis }}</p></details><details class="source-details"><summary>Inspect source</summary><dl><dt>Record ID</dt><dd>{{ focused.id }}</dd><dt>Source occurrence</dt><dd>{{ focused.source.path }}{{ focused.source.recordPointer }}</dd><dt>File availability</dt><dd>{{ focused.available ? 'Available locally' : 'Missing original' }}</dd></dl></details><div class="viewer-actions"><button class="btn btn-primary" @click="workspace.decide(focused.id, 'keep')">Keep this</button><button class="btn btn-secondary" @click="workspace.decide(focused.id, 'exclude')">Exclude</button></div></aside></div></section></div>
	<div v-if="preview" :ref="previewDialog" tabindex="-1" class="preview-overlay" role="dialog" aria-modal="true" aria-label="Review decision preview" @keydown.esc="preview = null"><section class="decision-preview card"><span class="eyebrow">Before you decide</span><h2>{{ preview.status === 'exclude' ? 'Leave this out of your collection?' : preview.status === 'keep' ? 'Keep this collection?' : 'Save this review for later?' }}</h2><p>{{ preview.description }}</p><p>{{ preview.ids.length }} explicit record IDs. Your original files will remain unchanged. You can undo this entire decision.</p><p v-if="preview.revision !== currentRevision" class="stale-preview" role="alert">Your collection changed. Close this preview and prepare the decision again.</p><div><button class="btn btn-primary" :disabled="preview.revision !== currentRevision" @click="applyPreview">Apply {{ preview.status }}</button><button class="btn btn-secondary" @click="preview = null">Cancel</button></div></section></div>
	</div>
</template>

<style scoped>
.library-page{padding-top:58px}.library-heading{display:flex;justify-content:space-between;align-items:end;gap:40px;margin-bottom:34px}.library-heading h1{font-size:clamp(3rem,5vw,4.8rem);margin-top:12px}.collection-note{text-align:right;color:var(--text-soft);padding-bottom:8px}.collection-note>span{font:3.5rem var(--font-serif);color:var(--secondary);line-height:1}.collection-note p{font-size:.83rem}.collection-note a{display:inline-block;margin-top:14px;font-size:.87rem;border-bottom:1px solid var(--secondary);color:var(--secondary)}.review-toolbar{display:flex;justify-content:space-between;align-items:center;gap:20px;margin:22px 0;color:var(--text-soft);font-size:.76rem}.review-toolbar>div{display:flex;gap:8px}.review-toolbar button{border:1px solid var(--border);border-radius:20px;padding:6px 12px;background:transparent;font:inherit;color:var(--text)}button:disabled{opacity:.38;cursor:default}.library-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:24px}.memory-card{padding:12px;background:#fffaf2;border:1px solid var(--border);border-radius:18px;box-shadow:0 8px 20px #46351b06;transition:transform 160ms}.memory-card:hover{transform:translateY(-3px)}.memory-card.kept{border-color:#56836a}.memory-card.excluded{opacity:.6}.memory-card.selected{outline:2px solid var(--secondary);outline-offset:3px}.memory-top{display:flex;gap:8px;align-items:center;margin:0 3px 12px;font-size:.65rem;text-transform:uppercase;letter-spacing:.06em;color:var(--text-soft)}.selection-check{display:flex;align-items:center;gap:8px}.selection-check input{accent-color:var(--secondary)}.source-tag{margin-left:auto}.status-tag{color:var(--secondary);font-weight:700}.open-asset{display:block;width:100%;border:0;padding:0;background:none;text-align:inherit}.memory-caption{padding:16px 8px 8px}.memory-caption h2{font:1.6rem var(--font-serif)}.memory-caption p{margin-top:5px;font-size:.73rem;color:var(--text-soft);display:flex;justify-content:space-between}.memory-caption p span{text-transform:uppercase;letter-spacing:.08em;font-size:.64rem}.memory-actions{display:flex;gap:6px;padding:6px 8px 4px}.memory-actions button{border:0;border-radius:20px;background:transparent;padding:6px 13px;color:var(--text-soft);font-size:.7rem}.memory-actions button.active{background:var(--secondary-soft);color:var(--secondary)}.batch-bar{display:flex;align-items:center;justify-content:space-between;gap:15px;padding:16px 20px;background:#1f6958;color:#fff5e1;border-radius:12px;margin-bottom:20px;font-size:.8rem}.batch-bar>div{display:flex;gap:10px}.batch-bar button{color:#fff5e1;border:1px solid #fff5e155;border-radius:20px;background:transparent;padding:7px 13px;font-size:.72rem}.library-footnote{text-align:center;max-width:650px;margin:35px auto 0;font-size:.78rem;color:var(--text-soft)}.load-more{display:block;margin:35px auto}.empty-library{display:grid;gap:20px;justify-items:center;text-align:center;padding:65px 30px}.empty-library h2{font-size:2rem}.empty-library p{max-width:450px;color:var(--text-soft)}.viewer-overlay,.preview-overlay{position:fixed;inset:0;z-index:150;background:#181710bd;display:grid;place-items:center;padding:35px}.memory-viewer{background:var(--bg);width:min(1100px,94vw);max-height:90vh;overflow:auto;padding:24px;border-radius:20px}.close-viewer{display:block;margin-left:auto;margin-bottom:16px;border:0;background:var(--secondary-soft);color:var(--secondary);padding:8px 20px;border-radius:20px}.viewer-layout{display:grid;grid-template-columns:minmax(0,1.5fr) minmax(270px,1fr);gap:28px}.viewer-layout aside{padding:5px 0}.viewer-layout h2{font:2.3rem var(--font-serif);margin:10px 0}.viewer-layout p{font-size:.84rem;color:var(--text-soft);margin:10px 0}.viewer-layout h3{font-size:.95rem;margin:28px 0 15px}.context-link{display:block;background:var(--secondary-soft);padding:14px 16px;border-radius:12px;margin:10px 0;font-weight:700;font-size:.86rem}.context-link small{display:block;font-weight:400;margin:4px 0;white-space:pre-wrap;overflow-wrap:anywhere;max-height:100px;overflow:auto}.context-link span{display:block;font-size:.69rem;color:var(--secondary);margin-top:10px}.source-details,.association-evidence{font-size:.74rem;margin-top:16px;color:var(--text-soft)}.source-details summary,.association-evidence summary{cursor:pointer}.source-details dt{margin-top:12px}.source-details dd{margin:0;color:var(--text);overflow-wrap:anywhere}.viewer-actions{display:flex;gap:10px;margin-top:22px}.viewer-actions .btn{font-size:.8rem;padding:10px 18px}.decision-preview{max-width:620px;padding:35px}.decision-preview h2{font:2.5rem var(--font-serif);margin:14px 0 20px}.decision-preview p{color:var(--text-soft);margin:14px 0;font-size:.9rem}.decision-preview>div{display:flex;gap:12px;margin-top:26px}.stale-preview{color:var(--danger)!important}.save-message{background:var(--secondary-soft);color:var(--secondary);border-radius:10px;padding:10px 15px;margin-bottom:20px;font-size:.82rem}@media(max-width:950px){.library-grid{grid-template-columns:repeat(2,1fr)}.review-toolbar{align-items:start;flex-direction:column}.viewer-layout{grid-template-columns:1fr}}@media(max-width:650px){.library-heading{display:block}.collection-note{text-align:left;margin-top:25px}.library-grid{grid-template-columns:1fr}.batch-bar{display:block}.batch-bar>div{flex-wrap:wrap;margin-top:12px}.review-toolbar>div{flex-wrap:wrap}}
</style>
